SELECT set_config('request.jwt.claim.sub','f49d6153-1835-4455-81f3-2918d5d3484e',false);
BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile group''s board debates a ''vertical integration'' expansion (acquiring a dyeing/finishing facility to bring an outsourced process in-house) using a ''transaction cost economics'' lens — the idea that firms internalize (own) an activity when the COST/RISK of coordinating it through an external market relationship exceeds the cost of managing it internally. Under this framework, what SPECIFIC condition would most strongly justify vertical integration into dyeing?', '["Vertical integration is never justified under any transaction-cost condition, making this entire analytical framework technically inapplicable to real sourcing decisions","If the specific dyeing process requires highly customized, PROPRIETARY technical knowledge/recipes (e.g., unique color-matching capability critical to the brand''s product) that''s difficult to fully specify/protect in an arm''s-length contract with an external supplier, and switching to a different external dye house would be costly/risky (echoing the earlier trial-order and new-factory-risk discussions) — this combination of asset specificity and contracting difficulty is the classic transaction-cost condition favoring internalizing (owning) the activity rather than continuing to source it externally","Vertical integration is only ever justified when the outsourced activity is completely GENERIC/COMMODITIZED with zero specialized knowledge requirement, the opposite of the actual transaction-cost-economics logic for when integration makes sense","Transaction cost economics has no relationship to vertical integration decisions, making this entire framework technically irrelevant to evaluating a dyeing-facility acquisition"]'::jsonb, 'If the specific dyeing process requires highly customized, PROPRIETARY technical knowledge/recipes (e.g., unique color-matching capability critical to the brand''s product) that''s difficult to fully specify/protect in an arm''s-length contract with an external supplier, and switching to a different external dye house would be costly/risky (echoing the earlier trial-order and new-factory-risk discussions) — this combination of asset specificity and contracting difficulty is the classic transaction-cost condition favoring internalizing (owning) the activity rather than continuing to source it externally', 'This applies genuine transaction-cost-economics theory (a foundational strategic management framework) to the earlier vertical-integration discussion, adding analytical rigor to WHEN integration makes sense — the classic condition favoring internalization is high ''asset specificity'' (the activity requires highly customized, hard-to-transfer or hard-to-contractually-protect knowledge/capability specific to this relationship) combined with contracting difficulty (hard to fully specify quality/performance in a contract, and switching suppliers is costly/risky) — when these conditions hold, the transaction costs of managing the relationship through an external MARKET contract exceed the costs of simply OWNING and internally managing the activity, which is precisely the theoretical justification for vertical integration beyond just the general capital-investment/control tradeoff discussed earlier.', 3, '{"transaction-cost-economics-integration"}'::text[]),
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile group''s CFO calculates ''Return on Invested Capital'' (ROIC) separately for its Spinning division, Weaving division, and Garment division, finding ROIC of 8%, 14%, and 22% respectively. A board member proposes REALLOCATING capital investment AWAY from Spinning (lowest ROIC) toward Garment (highest ROIC). What important caveat should the CFO raise before this reallocation decision is finalized?', '["No caveat is needed; capital should always be allocated purely based on which division shows the highest CURRENT ROIC, with zero additional consideration required for any other factor","ROIC differences between divisions in a VERTICALLY INTEGRATED group can partly reflect where in the value chain PROFIT MARGIN is conventionally captured/recorded (e.g., garment assembly often shows structurally higher margins than capital-intensive upstream spinning in most industry cost structures) rather than purely reflecting genuine relative INVESTMENT QUALITY — before reallocating capital away from Spinning, the CFO should assess whether reduced Spinning capacity would actually hurt the GROUP''s overall competitive position (e.g., losing backward-linkage advantages discussed earlier, or reduced supply security for the Weaving/Garment divisions), since these divisions aren''t necessarily independent, freestanding investment choices but interdependent parts of one integrated value chain","ROIC is calculated identically regardless of a division''s position in the value chain, making any caveat about value-chain-position-driven margin differences technically unfounded","Capital reallocation decisions within a vertically integrated group should always ignore ROIC entirely and rely purely on each division''s absolute revenue size instead"]'::jsonb, 'ROIC differences between divisions in a VERTICALLY INTEGRATED group can partly reflect where in the value chain PROFIT MARGIN is conventionally captured/recorded (e.g., garment assembly often shows structurally higher margins than capital-intensive upstream spinning in most industry cost structures) rather than purely reflecting genuine relative INVESTMENT QUALITY — before reallocating capital away from Spinning, the CFO should assess whether reduced Spinning capacity would actually hurt the GROUP''s overall competitive position (e.g., losing backward-linkage advantages discussed earlier, or reduced supply security for the Weaving/Garment divisions), since these divisions aren''t necessarily independent, freestanding investment choices but interdependent parts of one integrated value chain', 'This connects the earlier vertical-integration and backward-linkage discussions to a sophisticated capital-allocation caveat — in a vertically integrated group, different value-chain stages often show STRUCTURALLY different margin/ROIC profiles simply due to where in the chain profit is conventionally captured (not necessarily reflecting which stage is the ''better investment'' in isolation), AND the divisions are INTERDEPENDENT (Spinning capacity affects Weaving''s fabric supply security, which affects Garment''s production reliability) rather than independent, freestanding investment options — naively reallocating capital purely toward the highest-ROIC division without considering these value-chain interdependencies risks damaging the GROUP''s overall integrated competitive position, even if it looks like a straightforward capital-efficiency improvement when each division''s ROIC is viewed in isolation.', 3, '{"ROIC-vertical-integration-caveat"}'::text[]),
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile group''s strategy team applies the ''BCG Growth-Share Matrix'' (classifying business units by market growth rate and relative market share into ''Stars,'' ''Cash Cows,'' ''Question Marks,'' and ''Dogs'') to its product portfolio, classifying its basic commodity t-shirt line as a ''Cash Cow'' (low growth, high market share) and its technical/performance fabric line as a ''Question Mark'' (high growth, low market share). What STRATEGIC implication does this classification suggest for how CASH generated by each unit should be used?', '["Cash generated by the Cash Cow (basic t-shirt line) should be reinvested entirely back into that SAME low-growth business, while the Question Mark (technical fabric line) should receive no investment at all, the reverse of standard BCG matrix strategic logic","The classic BCG matrix logic suggests the Cash Cow (generating strong, stable cash flow from its high share but requiring little further growth investment since the market itself isn''t growing much) should FUND investment INTO the Question Mark (which needs capital to try to grow its market share in an attractive, high-growth market before that growth opportunity window closes) — using the mature business''s cash generation to fund the uncertain but potentially higher-future-value growth opportunity, rather than each business unit being expected to self-fund its own investment independently","The BCG matrix framework has no relationship to actual capital allocation strategy, making this entire classification exercise a purely academic categorization with zero practical resource-allocation implication","Both business units should receive mathematically identical capital investment regardless of their different BCG matrix classifications, making the classification exercise strategically meaningless"]'::jsonb, 'The classic BCG matrix logic suggests the Cash Cow (generating strong, stable cash flow from its high share but requiring little further growth investment since the market itself isn''t growing much) should FUND investment INTO the Question Mark (which needs capital to try to grow its market share in an attractive, high-growth market before that growth opportunity window closes) — using the mature business''s cash generation to fund the uncertain but potentially higher-future-value growth opportunity, rather than each business unit being expected to self-fund its own investment independently', 'This applies the classic BCG Growth-Share Matrix strategic logic to a real textile-group portfolio decision — a ''Cash Cow'' (high share in a low-growth market) typically generates strong, stable cash flow while requiring relatively little further investment (the market itself isn''t growing enough to justify heavy reinvestment), making it a natural SOURCE of capital; a ''Question Mark'' (low share in a high-growth market) requires significant capital investment to try to build market share while that growth opportunity is still available, but carries genuine uncertainty about whether that investment will succeed — the classic strategic recommendation is using the Cash Cow''s reliable cash generation to FUND the Question Mark''s growth investment, treating the portfolio as an interconnected capital-allocation system rather than expecting each business unit to be entirely self-funding in isolation.', 3, '{"BCG-matrix-capital-allocation"}'::text[]);
COMMIT;
